      { name: 'Direct Speech & Punctuation', questions: [{type:'trueFalse',q:'Direct speech shows exact words someone says.',answer:true},{type:'multiple',q:'Direct speech is enclosed in:',options:['dashes','brackets','inverted commas','parentheses'],answer:2},{type:'fillBlank',q:'"Hello," said Tom. The comma goes ____ the inverted commas.',answer:'inside',accept:['inside']},{type:'multiple',q:'Which is correctly punctuated?',options:['He said "I am happy".', '"I am happy" he said.', '"I am happy," he said.', 'He said I am happy.'],answer:2},{type:'trueFalse',q:'When a new speaker talks, you start a new line.',answer:true},{type:'fillBlank',q:'A ____ clause tells us who is speaking.',answer:'reporting',accept:['reporting']},{type:'multiple',q:'"Stop!" shouted Sarah. The exclamation mark:',options:['goes outside','goes inside','should be a full stop','is not needed'],answer:1},{type:'trueFalse',q:'"Have you finished?" asked Mum. This is correct.',answer:true},{type:'fillBlank',q:'The ____ clause comes before or after the speech.',answer:'reporting',accept:['reporting']},{type:'multiple',q:'Which shows direct speech correctly?',options:['She exclaimed what a view!', '"What a view!" she exclaimed.', 'What a view she exclaimed.', 'She exclaimed "what a view!".'],answer:1},{type:'trueFalse',q:'Direct speech can have a reporting clause at the end.',answer:true},{type:'fillBlank',q:'"Can you help?" ____ Tom.',answer:'asked',accept:['asked']},{type:'multiple',q:'"Look out!" called Jack. The exclamation mark is inside. This is:',options:['wrong','correct','optional','not needed'],answer:1},{type:'trueFalse',q:'A question mark inside inverted commas is correct: "Where are you?" asked Mum.',answer:true},{type:'fillBlank',q:'When speech starts a sentence, a ____ goes inside the inverted commas.',answer:'comma',accept:['comma']},{type:'multiple',q:'Choose correctly punctuated:',options:['"Goodbye", she whispered.', '"Goodbye" she whispered.', '"Goodbye" she whispered.', '"Goodbye" she whispered.'],answer:0},{type:'trueFalse',q:'Each new speaker gets a new paragraph.',answer:true},{type:'fillBlank',q:'"Come here!" ____ Dad.',answer:'shouted',accept:['shouted']},{type:'multiple',q:'Which is correct?',options:['"I love this!" smiled Tom.', '"I love this," smiled Tom.', '"I love this." smiled Tom.', 'I love this! smiled Tom.'],answer:0},{type:'trueFalse',q:'The reporting clause must always come after the speech.',answer:false},{type:'fillBlank',q:'"No!" was her ____ response.',answer:'immediate',accept:['immediate']}] },
      { name: 'Noun Phrases & Expansion', questions: [{type:'trueFalse',q:'A noun phrase is a group of words centred on a noun.',answer:true},{type:'multiple',q:'Which is a noun phrase?',options:['quickly run','the tall tree','very happy','is sleeping'],answer:1},{type:'fillBlank',q:'"The big red ball" has ____ adjectives before the noun.',answer:'two',accept:['two','2']},{type:'multiple',q:'Which expands the noun phrase "dog"?',options:['the dog','the big brown dog','a dog','it is a dog'],answer:1},{type:'trueFalse',q:'A prepositional phrase can expand a noun phrase.',answer:true},{type:'fillBlank',q:'"The girl in the red dress" has a ____ phrase expanding "girl".',answer:'prepositional',accept:['prepositional']},{type:'multiple',q:'Which noun phrase is expanded?',options:['a cat','the quick cat','cat','is a cat'],answer:1},{type:'trueFalse',q:'Articles are part of noun phrases.',answer:true},{type:'fillBlank',q:'In "the happy children", "happy" is an ____',answer:'adjective',accept:['adjective']},{type:'multiple',q:'Which has the best expansion?',options:['dog','a dog','the large, energetic dog with floppy ears','big dog'],answer:2},{type:'trueFalse',q:'Relative clauses can expand noun phrases.',answer:true},{type:'fillBlank',q:'"The car that was blue" uses a ____ clause.',answer:'relative',accept:['relative']},{type:'multiple',q:'Which adds detail to expand a noun?',options:['slowly','is','beautiful','ran'],answer:2},{type:'trueFalse',q:'"My favourite colourful toy" is a noun phrase.',answer:true},{type:'fillBlank',q:'A noun phrase can be expanded by adding ____.',answer:'adjectives',accept:['adjectives']},{type:'multiple',q:'Which uses an expanded noun phrase best?',options:['The cat is soft.','The soft, white cat with green eyes sat peacefully.','A cat sat.','The cat.'],answer:1},{type:'trueFalse',q:'The noun in "the running children" is "running".',answer:false},{type:'fillBlank',q:'"The old house on the hill" has a noun phrase with a ____',answer:'prepositional phrase',accept:['prepositional phrase']},{type:'multiple',q:'Which phrase does NOT expand "boy"?',options:['"the tall boy"', '"the boy with curly hair"', '"the happy"', '"the boy in blue"'],answer:2},{type:'trueFalse',q:'Noun phrases always have adjectives.',answer:false},{type:'fillBlank',q:'A ____ is the most essential word in a noun phrase.',answer:'noun',accept:['noun']}] },
      { name: 'Possessive Apostrophes', questions: [{type:'trueFalse',q:'A possessive apostrophe shows ownership.',answer:true},{type:'multiple',q:'Where does the apostrophe go in singular possession?',options:['before the s','after the s','at the end','in the middle'],answer:0},{type:'fillBlank',q:'The dog\'s bone belongs to one ____',answer:'dog',accept:['dog']},{type:'multiple',q:'Which is correct for one cat?',options:['cat\'s tail','cats\' tail','cats tail','cat tail'],answer:0},{type:'trueFalse',q:'The plural possessive apostrophe goes after the "s".',answer:true},{type:'fillBlank',q:'The dogs\' bone belongs to more than one ____',answer:'dog',accept:['dog']},{type:'multiple',q:'"The girls\' shoes" means shoes belong to:',options:['one girl','two girls','many girls','no one'],answer:2},{type:'trueFalse',q:'"Sarah\'s book" shows Sarah owns one book.',answer:true},{type:'fillBlank',q:'For plural words ending in "s", add an apostrophe ____ the s.',answer:'after',accept:['after']},{type:'multiple',q:'Which is correct?',options:['the childs toy','the child\'s toy','the childs\' toy','the child toy'],answer:1},{type:'trueFalse',q:'"The teachers\' room" means one teacher\'s room.',answer:false},{type:'fillBlank',q:'The boy\'s ____ is singular possession.',answer:'toy',accept:['toy','possessions']},{type:'multiple',q:'"The flowers\' petals" means:',options:['one flower','two flowers','many flowers','no flowers'],answer:2},{type:'trueFalse',q:'Irregular plurals like "children" take "\'s" for possession.',answer:true},{type:'fillBlank',q:'"The children\'s playground" shows possession by ____ children.',answer:'many',accept:['many']},{type:'multiple',q:'Which is correctly punctuated?',options:['the womans coat','the woman\'s coat','the womans\' coat','the woman coat'],answer:1},{type:'trueFalse',q:'"The boys\' ball" shows one boy\'s ball.',answer:false},{type:'fillBlank',q:'Show a dog owns a bone: the dog\'s ____',answer:'bone',accept:['bone']},{type:'multiple',q:'"The kings\' crowns" means crowns belong to:',options:['one king','two kings','many kings','all kings'],answer:2},{type:'trueFalse',q:'Plural "s" words have apostrophe after the "s".',answer:true},{type:'fillBlank',q:'"The cat\'s toy" is ____ possession.',answer:'singular',accept:['singular']}] },
      { name: 'Standard English & Formal Language', questions: [{type:'trueFalse',q:'Standard English uses correct grammar and spelling.',answer:true},{type:'multiple',q:'Which is standard English?',options:['He don\'t like it','He doesn\'t like it','He do not like it','He doesn\'t likes it'],answer:1},{type:'fillBlank',q:'Subject-verb agreement means the subject and ____ must match.',answer:'verb',accept:['verb']},{type:'trueFalse',q:'Double negatives are correct in standard English: "I don\'t want nothing."',answer:false},{type:'multiple',q:'Which has correct subject-verb agreement?',options:['The children is happy.','The children are happy.','The child are happy.','The childs is happy.'],answer:1},{type:'fillBlank',q:'"I haven\'t got nothing" is a ____ negative.',answer:'double',accept:['double']},{type:'multiple',q:'Which is formal English?',options:['Yeah, I\'m gonna go','Yes, I am going to leave','I\'m gonna head off','Yeah, I\'ll go'],answer:1},{type:'trueFalse',q:'Informal language is acceptable in formal writing.',answer:false},{type:'fillBlank',q:'Formal language is more ____ and professional.',answer:'polite',accept:['polite']},{type:'multiple',q:'Which avoids a double negative?',options:['She don\'t want nothing','She doesn\'t want anything','She won\'t have no cake','She ain\'t got nothing'],answer:1},{type:'trueFalse',q:'The verb must agree with the subject.',answer:true},{type:'fillBlank',q:'In "They ____", the verb is plural.',answer:'are',accept:['are','were']},{type:'multiple',q:'Which is standard for disagreement?',options:['You\'re wrong','I don\'t agree','That ain\'t right','I can\'t agree with that'],answer:3},{type:'trueFalse',q:'Contractions are acceptable in formal standard English.',answer:false},{type:'fillBlank',q:'"I ain\'t got time" standard form is "I ____"',answer:'haven\'t',accept:['haven\'t','have not']},{type:'multiple',q:'Which shows correct subject-verb agreement?',options:['The cats eats fish','The cat eat fish','The cat eats fish','The cats eats fish'],answer:2},{type:'trueFalse',q:'Standard English requires formal tone in all writing.',answer:false},{type:'fillBlank',q:'A ____ negative uses two negative words.',answer:'double',accept:['double']},{type:'multiple',q:'Which is standard and formal?',options:['She doesn\'t want none','She don\'t want nothing','She doesn\'t want anything','She doesn\'t wants anything'],answer:2},{type:'trueFalse',q:'"I goes to school" has correct agreement.',answer:false},{type:'fillBlank',q:'"Isn\'t" is a ____ of "is not".',answer:'contraction',accept:['contraction']}] },
      { name: 'Spelling: Prefixes, Suffixes & Word Families', questions: [{type:'multiple',q:'What does "anti-" mean?',options:['before','against','not','after'],answer:1},{type:'fillBlank',q:'"Auto-" means ____',answer:'self',accept:['self']},{type:'trueFalse',q:'"Unhappy" has the prefix "un-".',answer:true},{type:'multiple',q:'Which word has "inter-"?',options:['international','antifreeze','autobiography','untidy'],answer:0},{type:'fillBlank',q:'"Super-" means ____ or very.',answer:'above',accept:['above','extra']},{type:'trueFalse',q:'"Disappear" has "dis-" meaning "not".',answer:true},{type:'multiple',q:'What suffix makes a noun an adjective?',options:['-tion','-ment','-ous','-ing'],answer:2},{type:'fillBlank',q:'"Dangerous" is "danger" + ____',answer:'-ous',accept:['-ous','ous']},{type:'trueFalse',q:'"-ation" creates a noun.',answer:true},{type:'multiple',q:'Which has "-tion"?',options:['action','running','slowly','happy'],answer:0},{type:'fillBlank',q:'"-ment" creates a ____',answer:'noun',accept:['noun']},{type:'trueFalse',q:'"Un-" and "dis-" mean "not".',answer:true},{type:'multiple',q:'What word family does "cat" belong to?',options:['cats, catty, catfish','dog, cats','scatter, catastrophe','ate, cat, rat'],answer:0},{type:'fillBlank',q:'A word ____ is a group of related words.',answer:'family',accept:['family']},{type:'trueFalse',q:'"Hopeful" = "hope" + "-ful".',answer:true},{type:'multiple',q:'Which prefix means "many"?',options:['mono-','multi-','semi-','auto-'],answer:1},{type:'fillBlank',q:'"Careful" is "care" + ____',answer:'-ful',accept:['-ful','ful']},{type:'trueFalse',q:'"Creation" is "create" + "-tion".',answer:true},{type:'multiple',q:'How do you spell "in-" + "active"?',options:['inacktive','inacive','inactive','in-active'],answer:2},{type:'fillBlank',q:'"Il-" means ____ (as in "illegal").',answer:'not',accept:['not']},{type:'fillBlank',q:'The suffix "-less" means without: care + ____ = careless.',answer:'-less',accept:['-less','less']}] }
